enum LooperTrackState {
  LOOPER_TRACK_EMPTY(0),

  /// waiting for the bar line to start recording
  LOOPER_TRACK_ARMED(1),
  LOOPER_TRACK_RECORDING(2),
  LOOPER_TRACK_PLAYING(3);

  final int value;
  const LooperTrackState(this.value);

  static LooperTrackState fromValue(int value) => switch (value) {
    0 => LOOPER_TRACK_EMPTY,
    1 => LOOPER_TRACK_ARMED,
    2 => LOOPER_TRACK_RECORDING,
    3 => LOOPER_TRACK_PLAYING,
    _ => throw ArgumentError("Unknown value for LooperTrackState: $value"),
  };
}

/// The most recent overdub layer of a track (one level of undo/redo).
enum LooperLayerState {
  LOOPER_LAYER_NONE(0),

  /// overdub in progress
  LOOPER_LAYER_RECORDING(1),

  /// audible; can be undone
  LOOPER_LAYER_ACTIVE(2),

  /// silent; can be redone
  LOOPER_LAYER_UNDONE(3);

  final int value;
  const LooperLayerState(this.value);

  static LooperLayerState fromValue(int value) => switch (value) {
    0 => LOOPER_LAYER_NONE,
    1 => LOOPER_LAYER_RECORDING,
    2 => LOOPER_LAYER_ACTIVE,
    3 => LOOPER_LAYER_UNDONE,
    _ => throw ArgumentError("Unknown value for LooperLayerState: $value"),
  };
}

