  external double metronome_volume;

  @ffi.Array.multi([16])
  external ffi.Array<ffi.Float> input_peaks;

  @ffi.Array.multi([8])
  external ffi.Array<LooperTrackStatus> tracks;
}

const int LOOPER_MAX_TRACKS = 8;

const int LOOPER_MAX_INPUTS = 16;
